/**
 * Get HTTP URL for proxy service based on the provided port.
 *
 * @param {string} port - TCP/IP port for HTTP connection
 * @returns {string} - Combined URL in the format "http://<address>:<port>/docs"
 */
function getProxyServiceUrl(port) {
    let url = window.location.href;
    let address = url.split("/")[2].split(":")[0]; // Extract the IP address
    return `http://${address}:${port}/docs`;
}

